  Lemma pre_inv : mem_inv bsegs VM.
  Proof.
    intros a b H. unfold ro_addr. rewrite bsegs_ASEGS.
    destruct (find_segment BSEGS2 (bv_unsigned a) 1) as [seg|] eqn:Hf; [|reflexivity].
    apply find_segment_some_spec in Hf as (Hin & Hb & Ht). rewrite both_segs_eq in Hin.
    destruct (seg_writable seg) eqn:SW; [reflexivity|]. exfalso.
    assert (HR : 0x10000 <= bv_unsigned a < 0x119000).
    { destruct Hin as [<-|[<-|[<-|[<-|[]]]]]; cbn in Hb, Ht, SW; try discriminate SW; lia. }
    pose proof (img_none_main 0x10000 0x119000 ltac:(vm_cast_no_check (@eq_refl bool true)) (bv_unsigned a) HR) as N.
    replace (Z_to_bv 64 (bv_unsigned a)) with a in N by (apply bv_eq; rewrite Z_to_bv_unsigned; symmetry; apply bv_wrap_small; apply bv_unsigned_in_range). congruence.
  Qed.

